#nullable enable // autogenerated

using System;
using MVZ2.Level.Inputing;
using MVZ2Logic.Models;
using PVZEngine;
using PVZEngine.Tools.Unity;
using UnityEngine;

namespace MVZ2.GameContent.Customize
{
    public class TeleporterTeamLayoutUI : MonoBehaviour
    {
        public void SetTileCount(int count)
        {
            tilesList.updateList(count, null, go =>
            {
                var tile = go.GetComponent<TeleporterTeamLayoutTileUI>();
                tile.OnPointerInteraction += OnTilePointerInteractionCallback;
            },
            go =>
            {
                var tile = go.GetComponent<TeleporterTeamLayoutTileUI>();
                tile.OnPointerInteraction -= OnTilePointerInteractionCallback;
            });
        }
        public void SetTileHighlight(int index, Color color)
        {
            var tile = tilesList.getElement<TeleporterTeamLayoutTileUI>(index);
            if (tile.Exists())
            {
                tile.SetHighlightColor(color);
            }
        }
        public void ClearTiles()
        {
            foreach (var tile in tilesList.getElements<TeleporterTeamLayoutTileUI>())
            {
                tile.ClearLayerModels();
            }
        }
        public void AddTileEntity(int index, NamespaceID entityID, IModelBuilder modelBuilder, string? sortingLayer, int sortingOrder)
        {
            var tile = tilesList.getElement<TeleporterTeamLayoutTileUI>(index);
            if (tile == null)
                return;
            tile.AddEntityModel(entityID, modelBuilder, sortingLayer, sortingOrder);
        }
        public void RemoveTileEntity(int index, NamespaceID entityID)
        {
            var tile = tilesList.getElement<TeleporterTeamLayoutTileUI>(index);
            if (tile == null)
                return;
            tile.RemoveEntityModel(entityID);
        }
        private void OnTilePointerInteractionCallback(TeleporterTeamLayoutTileUI tile, PointerInteractionArgs args)
        {
            OnPointerInteraction?.Invoke(tilesList.indexOf(tile), args);
        }
        public event Action<int, PointerInteractionArgs>? OnPointerInteraction;
        [SerializeField]
        private ElementList tilesList = null!;
    }
}
